export const toFrames = (s: number) => Math.max(0, Math.round(s * FPS));

export interface Piece {
  index: number;
  from: number;
  durF: number;
  clip: MainClip;
  /** Frame inside the clip's own file this piece starts at. */
  srcFrom: number;
}

/** The main track laid end to end. Same maths as the editor's buildClips (no padding). */
export function mainPieces(p: Pick<PromoProps, "clipList" | "clipDurations" | "clipSourceOffsets">): Piece[] {
  let from = 0;
  return p.clipList.map((clip, index) => {
    const durF = Math.max(1, toFrames(p.clipDurations[index] ?? 3));
    const piece = { index, from, durF, clip, srcFrom: toFrames(p.clipSourceOffsets[index] ?? 0) };
    from += durF;
    return piece;
  });
}

/** Total length: the main track, or the last overlay clip if it runs longer. */
export function totalFrames(p: Pick<PromoProps, "clipList" | "clipDurations" | "clipSourceOffsets" | "extraTracks">): number {
  const pieces = mainPieces(p);
  const last = pieces[pieces.length - 1];
  let end = last ? last.from + last.durF : 1;
  for (const t of p.extraTracks ?? []) for (const c of t.clips ?? []) end = Math.max(end, Math.round(c.startFrame + c.durationFrames));
  return Math.max(1, end);
}

export const totalSeconds = (p: PromoProps) => totalFrames(p) / FPS;

export function aspectRatio(a: Exclude<MediaAspect, "full">): number {
  const [w, h] = a.split(":").map(Number);
  return w / h;
}

/** Where the media band sits in a frame of this size: full width, vertically centred. */
export function bandBox(layout: Pick<Layout, "mediaAspect">, width = WIDTH, height = HEIGHT) {
  if (layout.mediaAspect === "full") return { top: 0, height, bottom: height, full: true };
  const h = Math.min(height, Math.round(width / aspectRatio(layout.mediaAspect)));
  const top = Math.round((height - h) / 2);
  return { top, height: h, bottom: top + h, full: h >= height * 0.8 };
}

/** "Try *this*" → [{text:"Try ",accent:false},{text:"this",accent:true}] */
export function parseAccent(text: string): { text: string; accent: boolean }[] {
  return text.split(/(\*[^*]+\*)/g).filter(Boolean).map((part) => (part.startsWith("*") && part.endsWith("*") && part.length > 2 ? { text: part.slice(1, -1), accent: true } : { text: part, accent: false }));
}

/** The text above a main-track clip. */
export const clipText = (p: Pick<PromoProps, "videoScript">, i: number) => {
  const s = p.videoScript[i];
  return (s?.contentText ?? s?.ContentText ?? "") as string;
};
